using System;
using System.Collections.Generic;
using System.Linq;
using Comfort.Common;
using EFT;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class AiPairTransfer {
 sealed record Row(string Key,LiveActorReference Actor,string Role,bool Savage,string Detail,float Distance);
 static readonly List<Row> roster=new();static readonly AiPairSelection selection=new();static IntPtr world;static float nextScan;static string sourceQuery="",targetQuery="",message="";static AiTypeFilter sourceType,targetType;static bool sourceTypesOpen,targetTypesOpen;static Vector2 sourceScroll,targetScroll,sourceTypeScroll,targetTypeScroll;
 static string Key(Player actor)=>actor.ProfileId+"@"+actor.Pointer.ToInt64();
 internal static void Reset(){roster.Clear();selection.Clear();world=IntPtr.Zero;nextScan=0;message="";sourceTypesOpen=targetTypesOpen=false;sourceQuery=targetQuery="";sourceType=targetType=AiTypeFilter.All;sourceScroll=targetScroll=Vector2.zero;}
 static void Refresh(){var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current==null){Reset();return;}if(world!=current.Pointer){Reset();world=current.Pointer;}if(Time.unscaledTime<nextScan)return;nextScan=Time.unscaledTime+1;roster.Clear();var all=current.AllAlivePlayersList;var origin=current.MainPlayer?.Position??Vector3.zero;if(all!=null)for(int i=0;i<all.Count;i++)try{var actor=all[i];if(actor==null||actor.IsYourPlayer||!actor.IsAI||actor.HealthController?.IsAlive!=true)continue;string role=actor.Profile?.Info?.Settings?.Role.ToString()??"";bool savage=actor.Profile?.Side==EPlayerSide.Savage;string team=actor.AIData?.BotOwner is BotOwner owner?AiActorControl.Team(owner):"未分队";roster.Add(new(Key(actor),new(current,actor),role,savage,RolePalette.Name(RolePalette.Classify(role,savage))+" · "+team,Vector3.Distance(origin,actor.Position)));}catch{}roster.Sort((a,b)=>a.Distance.CompareTo(b.Distance));if(selection.Prune(roster.Select(row=>row.Key).ToHashSet(StringComparer.Ordinal)))message="部分 AI 已离开，请检查当前选择。";}
 internal static void Prefill(GameWorld current,IEnumerable<Player> actors){Reset();world=current.Pointer;Refresh();foreach(var actor in actors)if(actor!=null&&!actor.IsYourPlayer&&actor.IsAI){string key=Key(actor);if(roster.Any(row=>row.Key==key))selection.ToggleSource(key);}sourceQuery=targetQuery="";sourceType=targetType=AiTypeFilter.All;sourceScroll=targetScroll=Vector2.zero;}
 static void Column(Rect rect,bool source){float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w,28),source?"1. 来源 AI · 已选 "+selection.Count+"（可多选）":"2. 目标 AI · 保持原位",InterfaceMenu.Accent,14);y+=38;float typeWidth=Math.Min(140,w*.4f);string query=source?sourceQuery:targetQuery;query=InterfaceMenu.Field(new Rect(x,y,w-typeWidth-10,32),query);if(source)sourceQuery=query;else targetQuery=query;var type=source?sourceType:targetType;bool open=source?sourceTypesOpen:targetTypesOpen;if(InterfaceMenu.Button(new Rect(x+w-typeWidth,y,typeWidth,32),"类型："+AiTypeRules.Name(type)))open=!open;y+=44;
  var view=new Rect(x,y,w,Math.Max(50,rect.yMax-y));if(open){var filterScroll=source?sourceTypeScroll:targetTypeScroll;AiTypePicker.Options(view,ref type,ref open,ref filterScroll);if(source){sourceType=type;sourceTypeScroll=filterScroll;sourceTypesOpen=open;}else{targetType=type;targetTypeScroll=filterScroll;targetTypesOpen=open;}return;}if(source)sourceTypesOpen=false;else targetTypesOpen=false;
  var rows=roster.Where(row=>AiTypeRules.Matches(type,row.Role,row.Savage)&&(row.Actor.Name+" "+row.Detail+" "+row.Role).Contains(query,StringComparison.OrdinalIgnoreCase)).ToArray();var scroll=source?sourceScroll:targetScroll;scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,w-20,Math.Max(view.height-1,rows.Length*68)));int first=Math.Max(0,(int)(scroll.y/68)),end=Math.Min(rows.Length,first+(int)Math.Ceiling(view.height/68)+2);for(int i=first;i<end;i++){var row=rows[i];bool selected=source?selection.Contains(row.Key):selection.Target==row.Key;bool old=GUI.enabled;GUI.enabled=old&&(!source||selection.Target!=row.Key);string text=(selected?"✓  ":"")+row.Actor.Name+" · "+row.Distance.ToString("F0")+" 米\n"+row.Detail+(source&&selection.Target==row.Key?" · 当前目标":"");if(InterfaceMenu.WrappedButton(new Rect(0,i*68,w-26,60),text,selected)){if(source)selection.ToggleSource(row.Key);else selection.SelectTarget(row.Key);message="";}GUI.enabled=old;}if(rows.Length==0)InterfaceMenu.Label(new Rect(8,8,w-34,36),RaidClock.Active?"没有匹配的 AI":"进入战局后选择 AI",null,13);GUI.EndScrollView();if(source)sourceScroll=scroll;else targetScroll=scroll;
 }
 internal static void Draw(Rect rect){Refresh();float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w-126,30),"AI → AI 传送",InterfaceMenu.Accent,18);if(InterfaceMenu.Button(new Rect(x+w-116,y,116,30),"清空来源")){selection.ClearSources();message="";}y+=44;float half=(w-18)/2;var panels=new Rect(x,y,w,Math.Max(100,rect.yMax-y-128));Column(new Rect(panels.x,panels.y,half,panels.height),true);Column(new Rect(panels.x+half+18,panels.y,half,panels.height),false);
  var target=roster.FirstOrDefault(row=>row.Key==selection.Target);var moving=roster.Where(row=>selection.Contains(row.Key)).ToArray();string from=moving.Length==1?moving[0].Actor.Name:moving.Length+" 名 AI";string summary=selection.Ready?"将 "+from+" 传送到 "+target!.Actor.Name+" 旁边":"3. 左侧选要移动的 AI，右侧选目的地 AI";float bottom=rect.yMax-110;InterfaceMenu.Paragraph(new Rect(x,bottom,w-224,48),summary,null,14);bool old=GUI.enabled;GUI.enabled=old&&selection.Ready&&target!=null;if(InterfaceMenu.Button(new Rect(x+w-212,bottom,212,42),"传送到目标旁边")){TeleportControl.AiToAi(moving.Select(row=>row.Actor).ToArray(),target!.Actor);message=TeleportControl.LastNotice;}GUI.enabled=old;InterfaceMenu.Paragraph(new Rect(x,rect.yMax-54,w,50),message,InterfaceMenu.Accent,12);
 }
}
